const DONEV={flag:'Flagged in Outlook', unflag:'Unflagged in Outlook', read:'Marked read in Outlook', unread:'Marked unread in Outlook', move:'Filed in Outlook', del:'Moved to Deleted Items', book:'Booked — invites sent'};
