  const tl=h('div','nx-mo-tl'); nd.slice(0,40).forEach(t=>tl.appendChild(monthChip(t))); tray.appendChild(tl);
  tray.addEventListener('dragover', e=>{ if(!drag) return; e.preventDefault(); tray.classList.add('nx-over'); });
