      const sub=h('div','mtd-s'); sub.append('Next up '); sub.appendChild(h('b',null, nxt.day===tmo ? 'tomorrow' : mtShortDay(nxt.day))); sub.append(' · '+nxt.n+' meeting'+(nxt.n===1?'':'s')); mn.appendChild(sub);
